ALTER TABLE adc.practice_assignment ADD CHECK(row_version>0 AND (valid_to IS NULL OR valid_to>=valid_from));
ALTER TABLE adc.practice_revision ADD CHECK(version_no>0 AND (valid_to IS NULL OR valid_to>=valid_from));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['employee_revision','employee_revision_skill','practice_revision'] LOOP EXECUTE format('CREATE TRIGGER immutable_professional_history BEFORE UPDATE OR DELETE ON adc.%I FOR EACH ROW EXECUTE FUNCTION adc_auth.reject_history_change()',t);END LOOP;END $$;
CREATE FUNCTION adc_auth.employee_professional_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.employee_id IS DISTINCT FROM OLD.employee_id THEN RAISE EXCEPTION 'employee identity cannot move';END IF;
 IF ROW(NEW.name,NEW.contact_info,NEW.personal_profile,NEW.public_name,NEW.public_specialty,NEW.public_intro,NEW.public_enabled,NEW.professional_editor_id,NEW.professional_edited_at,NEW.row_version) IS DISTINCT FROM ROW(OLD.name,OLD.contact_info,OLD.personal_profile,OLD.public_name,OLD.public_specialty,OLD.public_intro,OLD.public_enabled,OLD.professional_editor_id,OLD.professional_edited_at,OLD.row_version) AND (NEW.row_version<>OLD.row_version+1 OR NEW.professional_editor_id IS NULL OR NEW.professional_edited_at IS NULL) THEN RAISE EXCEPTION 'professional change requires adjacent version and editor';END IF;RETURN NEW;END $$;
CREATE TRIGGER employee_professional_guard BEFORE UPDATE ON adc.employee FOR EACH ROW EXECUTE FUNCTION adc_auth.employee_professional_guard();
CREATE FUNCTION adc_auth.check_employee_professional() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE eid uuid; e adc.employee%ROWTYPE;rid uuid;BEGIN
 IF TG_TABLE_NAME='employee' THEN eid=NEW.employee_id;ELSE eid=COALESCE(NEW.employee_id,OLD.employee_id);END IF;SELECT * INTO STRICT e FROM adc.employee WHERE employee_id=eid;
 IF e.professional_editor_id IS NULL THEN RETURN NULL;END IF;
 SELECT employee_revision_id INTO rid FROM adc.employee_revision r WHERE r.employee_id=eid AND r.version_no=e.row_version AND ROW(r.name,r.contact_info,r.personal_profile,r.public_name,r.public_specialty,r.public_intro,r.public_enabled,r.professional_editor_id,r.professional_edited_at) IS NOT DISTINCT FROM ROW(e.name,e.contact_info,e.personal_profile,e.public_name,e.public_specialty,e.public_intro,e.public_enabled,e.professional_editor_id,e.professional_edited_at);
 IF rid IS NULL OR EXISTS((SELECT skill_name FROM adc.employee_skill WHERE employee_id=eid EXCEPT SELECT skill_name FROM adc.employee_revision_skill WHERE employee_revision_id=rid) UNION ALL (SELECT skill_name FROM adc.employee_revision_skill WHERE employee_revision_id=rid EXCEPT SELECT skill_name FROM adc.employee_skill WHERE employee_id=eid)) THEN RAISE EXCEPTION 'complete current employee revision and skills required';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER employee_professional_complete AFTER UPDATE ON adc.employee DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION adc_auth.check_employee_professional();
CREATE CONSTRAINT TRIGGER employee_skill_complete AFTER INSERT OR UPDATE OR DELETE ON adc.employee_skill DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION adc_auth.check_employee_professional();
CREATE FUNCTION adc_auth.practice_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.practice_id IS DISTINCT FROM OLD.practice_id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.clinic_id IS DISTINCT FROM OLD.clinic_id OR NEW.row_version<>OLD.row_version+1 THEN RAISE EXCEPTION 'practice identity and adjacent version required';END IF;RETURN NEW;END $$;
CREATE TRIGGER practice_identity_guard BEFORE UPDATE ON adc.practice_assignment FOR EACH ROW EXECUTE FUNCTION adc_auth.practice_identity_guard();
CREATE FUNCTION adc_auth.check_practice_revision() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM adc.practice_assignment p JOIN adc.practice_revision r ON r.practice_id=p.practice_id AND r.version_no=p.row_version WHERE p.practice_id=NEW.practice_id AND ROW(r.employee_id,r.clinic_id,r.valid_from,r.valid_to,r.practice_arrangement,r.affected_arrangements,r.updated_by,r.updated_at) IS NOT DISTINCT FROM ROW(p.employee_id,p.clinic_id,p.valid_from,p.valid_to,p.practice_arrangement,p.affected_arrangements,p.updated_by,p.updated_at)) THEN RAISE EXCEPTION 'complete current practice revision required';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER practice_complete AFTER UPDATE ON adc.practice_assignment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION adc_auth.check_practice_revision();
